UPDATE account_registration_item SET state=#{state},activation_id=#{activationId},phone_number=#{phoneNumber},
  actual_cost=#{actualCost},currency=#{currency},registration_id=#{registrationId},import_batch_id=#{importBatchId},
  account_id=#{accountId},failure_code=#{failureCode},started_at=#{startedAt},cancel_after=#{cancelAfter},updated_at=#{updatedAt}
WHERE id=#{id} AND lease_token=#{leaseToken} AND lease_until >= #{updatedAt}
